/** DEXORA application state, compatibility logic, comparison UI and event handlers. */
(() => {
  // Read store/part metadata from separate file. Region never restricts catalog.
  const {regions, categories, parts} = window.NEON_SEED;
  // All products are available worldwide in this local catalog; region/store only add verified links.
  // Missing price DOES NOT remove the product from selection.
  const extensions=window.NEON_CATALOG || {};
  for(const c of categories){
    const target=parts[c.id];
    const seenNames=new Set(target.map(p=>p.name.toLocaleLowerCase('vi-VN')));
    const seenIds=new Set(target.map(p=>p.id));
    for(const entry of (Array.isArray(extensions[c.id])?extensions[c.id]:[])){
      if(!entry?.id || !entry?.name || seenIds.has(entry.id) || seenNames.has(entry.name.toLocaleLowerCase('vi-VN')))continue;
      target.push({...entry}); seenIds.add(entry.id); seenNames.add(entry.name.toLocaleLowerCase('vi-VN'));
    }
  }
  for(const [category,group] of Object.entries(parts))for(const p of group)p.category=category;
  const catalogCount=()=>categories.reduce((total,c)=>total+parts[c.id].length,0);
  const isPriced=p=>Number.isFinite(p.price)&&p.price>0;

  const initial = {cpu:'i5',board:'b760d4',ram:'d4',gpu:'5070ti',ssd:'1tb',cooler:'aio360',case:'mid',psu:'850'};
  const presets = [
    {key:'budget',type:'01 // TIẾT KIỆM',name:'SMART VALUE',description:'Ưu tiên số tiền hợp lý, vẫn đảm bảo tương thích cơ bản.',items:{cpu:'r5',board:'b650',ram:'d5b',gpu:'5060ti',ssd:'1tb',cooler:'air',case:'mini',psu:'650'}},
    {key:'balance',type:'02 // CÂN BẰNG',name:'SWEET SPOT',description:'Cân đối chi phí cho game và làm việc đa nhiệm.',items:{cpu:'r7',board:'b650',ram:'d5',gpu:'5070',ssd:'1tb',cooler:'aio240',case:'mid',psu:'750'}},
    {key:'premium',type:'03 // HIỆU NĂNG',name:'FULL POWER',description:'Ưu tiên GPU cao hơn, tản và PSU đủ dự phòng.',items:{cpu:'i5',board:'b760d4',ram:'d4',gpu:'5070ti',ssd:'2tb',cooler:'aio360',case:'vision',psu:'850'}}
  ];
  // Discounted shop price is already final: NEVER subtract the discount rate again.
  // Price snapshots are generated by GitHub Actions. Missing/stale products retain DEMO prices.
  const priceRecords = new Map();
  let lastPriceSync = null;
  const formatVerified = iso => {
    const dt=new Date(iso);
    return Number.isFinite(dt.getTime()) ? dt.toLocaleString('vi-VN',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Ho_Chi_Minh'}) : '';
  };
  function priceDescriptor(product){
    const record=priceRecords.get(product.category+'/'+product.id);
    if(!record)return isPriced(product)?'GIÁ ƯỚC TÍNH (DEMO)':'CHƯA CÓ GIÁ • VẪN CHỌN ĐƯỢC';
    return 'GIÁ THAM KHẢO • '+formatVerified(record.last_verified)+(record.quotes?.some(q=>q.original_price>q.current_price)?' • ĐÃ GỒM GIÁ KHUYẾN MÃI':'');
  }
  function showPriceSync(){
    const status=document.getElementById('priceSync');if(!status)return;
    const available=priceRecords.size;
    status.classList.toggle('live',available>0);
    const total=categories.reduce((n,c)=>n+parts[c.id].length,0);
    status.lastElementChild.textContent=available
      ? `DỮ LIỆU GIÁ // ${available}/${total} linh kiện có giá từ cửa hàng được xác minh. Cập nhật gần nhất: ${formatVerified(lastPriceSync)}. Các món còn lại vẫn dùng giá demo.`
      : 'DỮ LIỆU GIÁ // Kho linh kiện độc lập cửa hàng. Mẫu chưa có báo giá vẫn chọn được; giá demo chỉ dành cho một số mẫu.';
  }
  async function syncShopPrices(){
    if(location.protocol==='file:'){showPriceSync();return;}
    try{
      const response=await fetch('./data/prices.json?t='+Date.now(),{cache:'no-store'});
      if(!response.ok)throw new Error('Không tải được dữ liệu giá');
      const payload=await response.json();
      if(payload.currency!=='VND'||!payload.entries||typeof payload.entries!=='object')throw new Error('Dữ liệu không hợp lệ');
      for(const c of categories){
        for(const p of parts[c.id]){
          const record=payload.entries[c.id+'/'+p.id];
          if(!record)continue;
          const t=new Date(record.last_verified).getTime();
          const age=Date.now()-t;
          if(!Number.isSafeInteger(record.estimate)||record.estimate<100000||record.estimate>250000000||!Number.isFinite(t)||age<0||age>7*86400000)continue;
          p.price=record.estimate;
          priceRecords.set(c.id+'/'+p.id,record);
          if(!lastPriceSync || t>new Date(lastPriceSync).getTime())lastPriceSync=record.last_verified;
        }
      }
      render();
    }catch(err){showPriceSync();}
  }
  const restored = (() => {try{return JSON.parse(localStorage.getItem('neon-rig-demo'))}catch{return null}})();
  let selected = {...initial,...(restored?.selected || {})};
  let regionId = regions.some(r=>r.id===restored?.regionId) ? restored.regionId : 'cantho';
  let storeId = restored?.storeId || '';
  const regionCurrent = () => regions.find(r=>r.id===regionId) || regions[0];
  const storeCurrent = () => regionCurrent().stores.find(s=>s.id===storeId) || regionCurrent().stores[0];
  let budget = Number.isFinite(restored?.budget) && restored.budget>=1000000 && restored.budget<=10000000000 ? restored.budget : 55000000;
  let page = 'build', usage = restored?.usage || 'gaming', catalogFilter = 'all', catalogQuery = '';
  let colorMode = ['white','black','mixed','any'].includes(restored?.colorMode)?restored.colorMode:'any';
  let colorPolicy = restored?.colorPolicy==='strict'?'strict':'prefer';

  let comparisonKey = null, comparisonLocked = false, comparisonExitTimer = null;
  let advisorComparisonIndex = null, advisorComparisonLocked = false, advisorComparisonExitTimer = null;
  const fmt = v => new Intl.NumberFormat('vi-VN').format(v)+' ₫';
  const estimateLabel = n => Number.isFinite(n)?'~'+fmt(n):'Chưa đủ dữ liệu giá';
  const esc = v => String(v).replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
  const get = (category,id) => parts[category].find(x=>x.id===id) || parts[category][0];
  const partOf = (category,items=selected) => get(category,items[category]);
  const priceOf = items => categories.every(c=>isPriced(get(c.id,items[c.id]))) ? categories.reduce((sum,c)=>sum+get(c.id,items[c.id]).price,0) : null;
  const missingPriceCount = items => categories.filter(c=>!isPriced(get(c.id,items[c.id]))).length;
  // Colors are independent from store and compatibility filtering.
  // Unknown color NEVER counts as an exact match, but still remains selectable.
  const visibleColorCategories=['board','ram','gpu','cooler','case','psu'];
  const colorNames={white:'FULL WHITE',black:'FULL BLACK',mixed:'BLACK & WHITE',any:'KHÔNG GIỚI HẠN'};
  const colorName={White:'Trắng',Black:'Đen',Silver:'Bạc'};
  const desiredColor=()=>colorMode==='white'?'White':colorMode==='black'?'Black':null;
  const colorOf=p=>p?.color==='White'||p?.color==='Black'||p?.color==='Silver'?p.color
    : /\bWhite$/i.test(p?.name||'')?'White':/\bBlack$/i.test(p?.name||'')?'Black':null;
  const colorClass=(category,p)=>{
    if(!visibleColorCategories.includes(category)||!desiredColor())return 'neutral';
    const found=colorOf(p);
    return found===desiredColor()?'match':found?'mismatch':'unknown';
  };
  const colorText=(category,p)=>{
    const state=colorClass(category,p);
    return state==='match'?'✓ Đúng màu':state==='mismatch'?'! Khác màu':state==='unknown'?'? Chưa rõ màu':'—';
  };
  // Sort compatible products by known estimated price (ascending), with missing prices last.
  // With a chosen appearance theme, exact-color products come first. This is a preference,
  // not a guarantee that the complete build matches the theme.
  const sortedColorChoices=(category,options)=>{
    const matchColor=Boolean(desiredColor()&&visibleColorCategories.includes(category));
    const rank={match:0,unknown:1,mismatch:2,neutral:3};
    return [...options].sort((a,b)=>{
      if(matchColor){
        const byColor=rank[colorClass(category,a)]-rank[colorClass(category,b)];
        if(byColor)return byColor;
      }
      const ap=isPriced(a)?a.price:Infinity, bp=isPriced(b)?b.price:Infinity;
      return ap-bp || a.name.localeCompare(b.name,'vi-VN');
    });
  };
  const colorReview=items=>{
    const out={matched:[],unknown:[],mismatch:[]};
    if(!desiredColor())return out;
    for(const cat of visibleColorCategories){
      const entry=partOf(cat,items),state=colorClass(cat,entry);
      if(state==='match')out.matched.push(cat);
      if(state==='unknown')out.unknown.push(cat);
      if(state==='mismatch')out.mismatch.push(cat);
    }
    return out;
  };
  function colorPanel(){
    const modes=[['white','FULL WHITE','Trắng'],['black','FULL BLACK','Đen'],['mixed','BLACK / WHITE','Phối'],['any','TÙY Ý','Tự do']];
    return `<section class="color-panel" aria-label="Chọn màu sắc cho bộ PC"><div class="color-head"><div><div class="kicker">// PHỐI MÀU PC</div><h3>Phối màu bộ PC</h3><p>Ưu tiên màu cho case, GPU, mainboard, RAM, tản nhiệt và nguồn. Danh mục không phụ thuộc cửa hàng.</p></div><span class="color-selected">${colorNames[colorMode]}</span></div><div class="color-modes">${modes.map(([id,label,desc])=>`<button type="button" class="color-tile ${colorMode===id?'chosen':''}" data-color-mode="${id}" aria-pressed="${colorMode===id}"><span class="color-swatch ${id}"></span><strong>${label}</strong><small>${desc}</small></button>`).join('')}</div><div class="color-bottom"><label><input type="checkbox" data-color-strict ${colorPolicy==='strict'?'checked':''} ${!desiredColor()?'disabled':''}> <strong>Chỉ áp dụng gợi ý đúng màu</strong></label><span>${colorPolicy==='strict'&&desiredColor()?'Không áp dụng phương án đề xuất nếu linh kiện nhìn thấy được chưa xác minh đúng màu.':'Ưu tiên linh kiện đúng màu nhưng vẫn hiển thị các lựa chọn khác.'}</span></div></section>`;
  }
  // Presets are still *illustrative*; matched-color substitutions preserve CPU,
  // same-class GPU, RAM capacity and connection standards whenever possible.
  const ramGB=p=>p.capacity??Number((p.name.match(/(\d+)GB/i)||[])[1]||0);
  const gpuChip=p=>(p.name.match(/(?:RTX\s*\d{4}(?:\s*Ti|\s*SUPER)?|RX\s*\d{4}(?:\s*XT|\s*XTX)?)/i)||[])[0]?.replace(/\s+/g,'').toLowerCase()||'';
  function themedPreset(base){
    if(!desiredColor())return {...base,items:{...base.items}};
    let items={...base.items};
    for(const cat of visibleColorCategories){
      const current=partOf(cat,items);
      if(colorOf(current)===desiredColor())continue;
      let options=compatibleOptions(cat,items).filter(p=>colorOf(p)===desiredColor());
      if(cat==='board')options=options.filter(p=>p.ram===current.ram&&p.form===current.form);
      if(cat==='gpu')options=options.filter(p=>gpuChip(p)===gpuChip(current)&&p.vram===current.vram);
      if(cat==='ram')options=options.filter(p=>p.ram===current.ram&&ramGB(p)===ramGB(current));
      if(cat==='cooler')options=options.filter(p=>p.rad===current.rad);
      if(cat==='psu')options=options.filter(p=>p.watts>=current.watts);
      if(!options.length)continue; // retain original, then disclose color mismatch/unknown
      items[cat]=options[0].id;
    }
    try{items=normalize(items).items;}catch{};
    return {...base,items};
  }
  const activePresets=()=>presets.map(themedPreset);
  const colorSummary=items=>{
    if(!desiredColor())return colorMode==='mixed'?'PHỐI ĐEN / TRẮNG':'KHÔNG RÀNG BUỘC MÀU';
    const r=colorReview(items);
    return `${r.matched.length}/${visibleColorCategories.length} món rõ màu ${colorName[desiredColor()].toLowerCase()} • ${r.unknown.length} chưa rõ • ${r.mismatch.length} khác màu`;
  };
  const requiredPSU = items => {
    const cpu=partOf('cpu',items),gpu=partOf('gpu',items);
    // Demo headroom, not a PSU manufacturer recommendation or cable/connector validation.
    return Math.ceil((cpu.watts + gpu.watts + 90)*1.2/50)*50;
  };
  const compatibleOptions = (category,items) => {
    const cpu=partOf('cpu',items),board=partOf('board',items),gpu=partOf('gpu',items),cooler=partOf('cooler',items);
    return parts[category].filter(p=>{
      switch(category){
        case 'board': return p.socket===cpu.socket;
        case 'ram': return p.ram===board.ram;
        case 'ssd': return p.slot==='M2' ? board.m2>0 : true;
        case 'cooler': return p.sockets.includes(cpu.socket) && (p.cap==null||p.cap>=cpu.watts);
        case 'case': return p.forms.includes(board.form) && (p.maxGpu==null||gpu.gpuLength==null||p.maxGpu>=gpu.gpuLength) && (p.maxRad==null||p.maxRad>=cooler.rad) && (cooler.rad>0||p.maxAir==null||p.maxAir>=cooler.coolerHeight);
        case 'psu': return p.watts>=requiredPSU(items);
        default: return true;
      }
    });
  };
  function normalize(items){
    const next={...initial,...items};
    const changes=[];
    for(const category of categories){
      const choices=compatibleOptions(category.id,next);
      if(!choices.length){ throw Error('Không có linh kiện '+category.id+' phù hợp trong dữ liệu mẫu'); }
      if(!choices.some(p=>p.id===next[category.id])){
        changes.push(category.id);
        next[category.id]=choices[0].id;
      }
    }
    return {items:next,changes};
  }
  selected=normalize(selected).items;
  const storeBrand = id => (id||'').split('-')[0];
  function productLink(p){const store=storeCurrent();return p.links?.[storeBrand(store.id)] || null;}
  function linkBelowPrice(p){const link=productLink(p);return link ? `<a class="shop-link" href="${esc(link)}" target="_blank" rel="noopener noreferrer" title="Link sản phẩm theo mã/phiên bản đã kiểm tra">XEM TẠI ${esc(storeCurrent().name)} ↗</a>` : '';}
  function assessment(items=selected){
    const cpu=partOf('cpu',items),board=partOf('board',items),ram=partOf('ram',items),cooler=partOf('cooler',items),cs=partOf('case',items),gpu=partOf('gpu',items),psu=partOf('psu',items);
    const messages=[
      {ok:cpu.socket===board.socket,label:`Socket: ${cpu.socket} ↔ mainboard ${board.socket}`},
      {ok:board.ram===ram.ram,label:`RAM: main ${board.ram} ↔ bộ nhớ ${ram.ram}`},
      {ok:cooler.sockets.includes(cpu.socket) ? (cooler.cap==null?null:cooler.cap>=cpu.watts):false,label:cooler.cap==null?'Tản nhiệt: cần kiểm tra ngàm lắp và khả năng làm mát theo phiên bản':'Tản nhiệt: phù hợp socket và công suất ước tính'},
      {ok:!cs.forms.includes(board.form)?false:(cs.maxGpu==null||gpu.gpuLength==null||cs.maxRad==null||cs.maxAir==null)?null:(cs.maxGpu>=gpu.gpuLength && cs.maxRad>=cooler.rad && (!cooler.coolerHeight||cs.maxAir>=cooler.coolerHeight)),label:'Case: khớp form factor; cần xác minh chiều dài GPU/radiator/tản khí nếu thiếu thông số'},
      {ok:psu.watts>=requiredPSU(items),label:`PSU: yêu cầu sơ bộ khoảng ${requiredPSU(items)}W`},
      {ok:priceOf(items)==null?null:priceOf(items)<=budget,label:priceOf(items)==null?'Ngân sách: còn '+missingPriceCount(items)+' món chưa có giá':'Tổng giá tham khảo '+(priceOf(items)<=budget?'nằm trong':'vượt')+' ngân sách'}
    ];
    const errors=messages.filter(m=>m.ok===false).length;
    const pending=messages.filter(m=>m.ok===null).length;
    const checked=messages.length-pending;
    return {messages,errors,pending,score:checked?Math.round((checked-errors)/checked*100):0};
  }
  const showToast = message => {const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove('show'),3000)};
  function save(){localStorage.setItem('neon-rig-demo',JSON.stringify({selected,budget,regionId,storeId,usage,colorMode,colorPolicy}));showToast('Đã lưu cấu hình vào trình duyệt');}
  function renderRegionToolbar(){
    const region=regionCurrent(),store=storeCurrent();
    document.getElementById('regionToolbar').innerHTML=`<div><label for="regionSelect">⌖ TỈNH/THÀNH THAM KHẢO</label><select id="regionSelect">${regions.map(r=>`<option value="${r.id}" ${r.id===regionId?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div><label for="storeSelect">⌗ CỬA HÀNG THAM KHẢO</label><select id="storeSelect">${region.stores.map(s=>`<option value="${s.id}" ${s.id===store.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="region-note"><strong>Kho linh kiện độc lập với tỉnh/thành và cửa hàng.</strong><small>Chọn ${esc(store.name)} chỉ để tra cứu link sản phẩm có thật ở cửa hàng đó; không lọc mất CPU, GPU hoặc các mẫu PC khác. Giá có thể gồm dữ liệu cửa hàng đã xác minh và dữ liệu demo; không phải báo giá chắc chắn.</small></div>`;
    document.getElementById('regionSelect').addEventListener('change',e=>{regionId=e.target.value;storeId=regionCurrent().stores[0].id;render();});
    document.getElementById('storeSelect').addEventListener('change',e=>{storeId=e.target.value;render();});
  }
  function renderStores(){const region=regionCurrent(),chosen=storeCurrent();return `<section class="section page-alt"><div class="page-intro"><div class="kicker">// STORE DISCOVERY • VIET NAM</div><h2>Cửa hàng PC tại ${esc(region.name)}</h2><p>Danh sách cửa hàng dùng để gợi ý địa chỉ và link mua hàng. <strong>Không giới hạn danh sách linh kiện ở phần tự build.</strong></p></div><div class="store-grid">${region.stores.map(s=>`<article class="store-card ${s.id===chosen.id?'selected':''}"><div class="store-head"><h3>${esc(s.name)}</h3><span class="kicker">${s.id===chosen.id?'● ĐANG CHỌN':'○ CỬA HÀNG'}</span></div><p>⌖ ${esc(s.address)}</p><div class="store-actions"><button class="btn ${s.id===chosen.id?'':'ghost'}" data-store="${s.id}">${s.id===chosen.id?'ĐÃ CHỌN':'CHỌN CỬA HÀNG'}</button><a href="${esc(s.website)}" target="_blank" rel="noopener noreferrer">Website ↗</a><a href="${esc(s.source)}" target="_blank" rel="noopener noreferrer">Nguồn showroom ↗</a></div></article>`).join('')}</div><div class="store-help">Các link mua hàng dưới giá linh kiện chỉ hiển thị khi có trang sản phẩm đúng mẫu/phiên bản tại cửa hàng chọn. Nếu thiếu URL, phần link sẽ để trống. Link có thể thay đổi hoặc hết hàng; cần kiểm tra trên website cửa hàng.</div></section>`;}
  function renderMetrics(){const sum=priceOf(selected),score=assessment().score;document.getElementById('metrics').innerHTML=`<div class="metric"><div class="name">Ngân sách mục tiêu</div><div class="value">${fmt(budget)}</div><div class="sub">Nhập trực tiếp ở phần tự build hoặc tư vấn</div></div><div class="metric"><div class="name">Chi phí cấu hình ước tính</div><div class="value ${sum==null?'cyan':sum>budget?'pink':'green'}">${estimateLabel(sum)}</div><div class="sub">Giá tham khảo toàn Việt Nam, không phụ thuộc cửa hàng đã chọn</div></div><div class="metric"><div class="name">Kiểm tra cơ bản</div><div class="value ${assessment().pending?'cyan':score===100?'cyan':'pink'}">${score}/100</div><div class="sub">6 điều kiện sơ bộ • chưa xác minh BIOS và dây cấp nguồn</div></div>`;}
  const budgetQuickValues=[20000000,30000000,40000000,50000000,70000000];
  const budgetDisplayNumber = n => new Intl.NumberFormat('vi-VN').format(n);
  function parseBudgetInput(raw){
    const s=String(raw).trim().toLowerCase().replace(/\s+/g,'');
    if(!s)return null;
    const million=s.match(/^([\d]+(?:[.,][\d]+)?)\s*(tr|triệu|m)$/);
    const amount=million ? Math.round(Number(million[1].replace(',','.'))*1000000) : (/^[\d.,]+$/.test(s) ? Number(s.replace(/[.,]/g,'')) : NaN);
    return Number.isSafeInteger(amount) && amount>=1000000 && amount<=10000000000 ? amount : null;
  }
  function budgetReport(){
    const total=priceOf(selected);
    if(total===null)return {total:null,delta:null,over:false,pct:0,label:'Chưa đủ dữ liệu giá để tính ngân sách',amount:missingPriceCount(selected)+' món chưa có giá'};
    const delta=budget-total,over=delta<0;
    const pct=Math.min(100,Math.round(total/budget*100));
    return {total,delta,over,pct,label:delta===0?'Vừa khớp ngân sách':over?'Vượt ngân sách':'Còn dư ngân sách',amount:delta===0?'~0 ₫':estimateLabel(Math.abs(delta))};
  }
  function budgetPanel(){
    const r=budgetReport();
    return `<div class="budget-panel"><div class="budget-top"><div><div class="budget-kicker">// NGÂN SÁCH DỰ KIẾN</div><div class="budget-sub">Nhập số tiền dự kiến chi cho toàn bộ PC, không bao gồm màn hình/phụ kiện.</div></div><div class="budget-expected" data-budget-total>Tổng hiện tại: ${estimateLabel(r.total)}</div></div><div class="budget-entry"><label class="budget-amount"><input type="text" data-budget-input inputmode="decimal" aria-label="Nhập ngân sách bằng đồng Việt Nam" value="${budgetDisplayNumber(budget)}" autocomplete="off" placeholder="VD: 35.000.000"><span>VNĐ</span></label><div class="budget-shortcuts">${budgetQuickValues.map(v=>`<button type="button" data-budget-quick="${v}" class="${v===budget?'active':''}">${v/1000000} triệu</button>`).join('')}</div></div><div class="budget-visual" role="progressbar" aria-label="Tỷ lệ tổng giá cấu hình trên ngân sách" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${r.pct}"><div class="budget-fill ${r.over?'over':''}" style="width:${r.pct}%"></div></div><div class="budget-result" data-budget-result><span>${r.label}</span><strong class="${r.over?'over':''}">${r.amount}</strong></div><div class="budget-hint">Có thể nhập 35000000, 35.000.000 hoặc 35tr • Một số giá có thể đã cập nhật, món thiếu dữ liệu vẫn dùng giá demo.</div></div>`;
  }
  function updateBudgetLive(){
    const r=budgetReport();
    renderMetrics();
    document.querySelectorAll('[data-budget-result]').forEach(el=>{el.innerHTML=`<span>${r.label}</span><strong class="${r.over?'over':''}">${r.amount}</strong>`});
    document.querySelectorAll('[data-budget-total]').forEach(el=>{el.textContent='Tổng hiện tại: '+estimateLabel(r.total)});
    document.querySelectorAll('.budget-fill').forEach(el=>{el.style.width=r.pct+'%';el.classList.toggle('over',r.over)});
    document.querySelectorAll('.budget-visual').forEach(el=>el.setAttribute('aria-valuenow',String(r.pct)));
    document.querySelectorAll('[data-budget-quick]').forEach(el=>el.classList.toggle('active',Number(el.dataset.budgetQuick)===budget));
  }
  // Comparison uses only known example metadata and estimated demo prices; not a benchmark engine.
  const compareSpecs = {
    ram:{d4:{gb:32},d4b:{gb:16},d5:{gb:32},d5b:{gb:16}},
    ssd:{'1tb':{gb:1000},'2tb':{gb:2000}},
    gpu:{'5060ti':{vram:16,tier:1},'5070':{vram:12,tier:2},'5070ti':{vram:16,tier:3}}
  };
  const millionText = v => (v/1000000).toLocaleString('vi-VN',{maximumFractionDigits:2})+' triệu';
  function comparisonAnalysis(p){
    const mine=selected,other=p.items,original=priceOf(mine),suggested=priceOf(other),delta=Number.isFinite(original)&&Number.isFinite(suggested)?suggested-original:null;
    const good=[],trade=[],notes=[];
    if(desiredColor()){
      const colors=colorReview(other);
      if(colors.mismatch.length)trade.push(`Phương án đề xuất có ${colors.mismatch.length} linh kiện khác màu ${colorName[desiredColor()].toLowerCase()} đang chọn.`);
      if(colors.unknown.length)notes.push(`Chưa xác minh màu của: ${colors.unknown.map(c=>c.toUpperCase()).join(', ')}. Không thể cam kết full ${colorMode}.`);
    }

    if(Number.isFinite(delta)&&delta<0)good.push(`Chi phí ước tính giảm ${millionText(Math.abs(delta))} so với bộ của bạn.`);
    if(Number.isFinite(delta)&&delta>0)trade.push(`Chi phí ước tính tăng ${millionText(delta)} so với bộ của bạn.`);
    if(!Number.isFinite(delta))notes.push('Chưa thể so sánh chi phí vì có sản phẩm chưa có giá xác minh hoặc giá demo.');
    const mineRam=partOf('ram',mine).capacity||compareSpecs.ram[mine.ram]?.gb,otherRam=partOf('ram',other).capacity||compareSpecs.ram[other.ram]?.gb;
    if(mineRam&&otherRam){if(otherRam>mineRam)good.push(`RAM tăng từ ${mineRam}GB lên ${otherRam}GB, có thêm dung lượng cho đa nhiệm.`);if(otherRam<mineRam)trade.push(`RAM giảm từ ${mineRam}GB xuống ${otherRam}GB, có thể hạn chế tác vụ nặng.`);}
    const mineSsd=partOf('ssd',mine).capacity||compareSpecs.ssd[mine.ssd]?.gb,otherSsd=partOf('ssd',other).capacity||compareSpecs.ssd[other.ssd]?.gb;
    if(mineSsd&&otherSsd){if(otherSsd>mineSsd)good.push(`Dung lượng SSD tăng từ ${mineSsd/1000}TB lên ${otherSsd/1000}TB.`);if(otherSsd<mineSsd)trade.push(`Dung lượng SSD giảm từ ${mineSsd/1000}TB xuống ${otherSsd/1000}TB.`);}
    const mineGPU={...compareSpecs.gpu[mine.gpu],vram:partOf('gpu',mine).vram??compareSpecs.gpu[mine.gpu]?.vram},otherGPU={...compareSpecs.gpu[other.gpu],vram:partOf('gpu',other).vram??compareSpecs.gpu[other.gpu]?.vram};
    if(mineGPU&&otherGPU){
      if(Number.isFinite(otherGPU.tier)&&Number.isFinite(mineGPU.tier)&&otherGPU.tier>mineGPU.tier)good.push(`GPU thuộc phân khúc sản phẩm cao hơn; cần benchmark để kết luận mức tăng FPS.`);
      if(Number.isFinite(otherGPU.tier)&&Number.isFinite(mineGPU.tier)&&otherGPU.tier<mineGPU.tier)trade.push(`GPU thuộc phân khúc sản phẩm thấp hơn; cần benchmark để biết FPS chênh bao nhiêu.`);
      if(otherGPU.vram>mineGPU.vram)good.push(`VRAM GPU tăng từ ${mineGPU.vram}GB lên ${otherGPU.vram}GB.`);
      if(otherGPU.vram<mineGPU.vram)trade.push(`VRAM GPU giảm từ ${mineGPU.vram}GB xuống ${otherGPU.vram}GB.`);
    }
    const minePsu=partOf('psu',mine).watts,otherPsu=partOf('psu',other).watts;
    if(otherPsu<minePsu)trade.push(`Nguồn giảm từ ${minePsu}W xuống ${otherPsu}W; ngưỡng tải hiện chỉ được kiểm tra sơ bộ.`);
    if(otherPsu>minePsu)good.push(`Nguồn tăng từ ${minePsu}W lên ${otherPsu}W, có thêm công suất danh định.`);
    if(partOf('cpu',mine).socket!==partOf('cpu',other).socket)notes.push('Đổi nền tảng CPU sẽ kéo theo đổi socket/mainboard; cần kiểm tra BIOS và linh kiện thực tế.');
    if(partOf('board',mine).ram!==partOf('board',other).ram)notes.push('Chuẩn RAM DDR4/DDR5 thay đổi theo mainboard, không thể dùng lẫn.');
    if(Number.isFinite(suggested)&&suggested>budget)trade.push(`Phương án vượt ngân sách nhập vào ${millionText(suggested-budget)} (giá tham khảo, có thể gồm dữ liệu demo).`);
    const changed=categories.filter(c=>mine[c.id]!==other[c.id]);
    if(!good.length)good.push('Chưa đủ dữ liệu đáng tin cậy để xác định ưu thế hiệu năng rõ ràng.');
    if(!trade.length)trade.push('Chưa xác định được đánh đổi quan trọng từ thông số hiện có; cần kiểm tra thêm khi chọn mua.');
    return {original,suggested,delta,good,trade,notes,changed};
  }
  function comparisonMarkup(p){
    const a=comparisonAnalysis(p),difference=!Number.isFinite(a.delta)?'Chưa đủ dữ liệu giá':a.delta===0?'Ước tính ngang giá':a.delta<0?`Tiết kiệm ${millionText(-a.delta)}`:`Tốn thêm ${millionText(a.delta)}`;
    const impactStyle=!Number.isFinite(a.delta)||a.delta===0?'neutral':a.delta<0?'good':'warn';
    return `<div class="compare-top"><div><div class="kicker">◈ PHÂN TÍCH CẤU HÌNH / ${esc(p.type)}</div><h3>${esc(p.name)} <span style="color:var(--acid)">so với</span> CẤU HÌNH CỦA BẠN</h3><p>Phân tích từng điểm khác biệt — không chỉ nhìn tổng giá.</p></div><div class="compare-top-actions"><button type="button" class="compare-close" data-close-comparison aria-label="Đóng bảng phân tích">✕ ĐÓNG</button></div></div>
      <div class="compare-vs"><div><div class="vs-label">01 / CẤU HÌNH CỦA BẠN</div><div class="vs-price">${estimateLabel(a.original)}</div></div><div class="vs-middle">VS</div><div><div class="vs-label">02 / ${esc(p.name)}</div><div class="vs-price suggested">${estimateLabel(a.suggested)}</div></div></div>
      <div class="compare-impact"><span class="impact-pill ${impactStyle}">${!Number.isFinite(a.delta)?'?':a.delta<0?'↘':a.delta>0?'↗':'＝'} ${esc(difference)}</span><span class="impact-pill neutral">↔ ${a.changed.length}/8 linh kiện khác nhau</span><span class="impact-pill ${!Number.isFinite(a.suggested)?'neutral':a.suggested>budget?'warn':'good'}">${!Number.isFinite(a.suggested)?'Chưa đủ dữ liệu giá':a.suggested>budget?'⚠ Vượt ngân sách':'✓ Trong ngân sách dự kiến'}</span></div>
      <div class="insight-grid"><section class="insight-box"><h4>✦ ĐIỂM CÓ LỢI</h4><ul>${a.good.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="insight-box tradeoff"><h4>⚠ ĐIỂM PHẢI ĐÁNH ĐỔI</h4><ul>${a.trade.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section></div>
      <div class="diff-head"><h4>↗ KHÁC BIỆT LINH KIỆN</h4><small>${a.changed.length} THAY ĐỔI / 8 VỊ TRÍ</small></div>
      <div class="diff-list">${a.changed.length?a.changed.map(c=>`<div class="diff-item"><span class="diff-part">${esc(c.short)}</span><span class="diff-from">${esc(partOf(c.id,selected).name)}</span><span class="diff-arrow">→</span><span class="diff-to">${esc(partOf(c.id,p.items).name)}</span></div>`).join(''):'<div class="diff-item"><span class="diff-part">✓</span><span class="diff-from">Cùng linh kiện</span><span class="diff-arrow">→</span><span class="diff-to">Không cần thay đổi</span></div>'}</div>
      ${a.notes.length?`<div class="compare-explain">${a.notes.map(x=>`<div>• ${esc(x)}</div>`).join('')}</div>`:''}
      <div class="compare-explain"><strong>Lưu ý:</strong> Giá, cấu hình đề xuất và một số thông số đang dùng dữ liệu demo. Phân tích này dựa trên thay đổi linh kiện và dung lượng, <strong>không phải FPS/benchmark đã đo</strong> hoặc xác nhận tương thích để đặt mua.</div>
      <div class="compare-actions-bottom"><button class="btn primary" data-apply="${p.key}">ÁP DỤNG PHƯƠNG ÁN ↗</button><button class="btn ghost" data-open-full-compare>XEM BẢNG SO SÁNH ĐẦY ĐỦ ⇄</button></div>`;
  }
  function updateComparisonUI(){
    const shell=document.querySelector('[data-compare-stage]'); if(!shell)return;
    const isOpen=!!comparisonKey;
    shell.classList.toggle('is-open',isOpen);
    shell.querySelectorAll('[data-option]').forEach(card=>{
      card.classList.toggle('is-selected',isOpen&&card.dataset.option===comparisonKey);
      card.classList.toggle('is-muted',isOpen&&card.dataset.option!==comparisonKey);
    });
    shell.querySelectorAll('[data-compare]').forEach(btn=>btn.setAttribute('aria-pressed',String(isOpen&&btn.dataset.compare===comparisonKey&&comparisonLocked)));
    const status=shell.querySelector('[data-motion-status]');
    if(status){status.textContent=(isOpen ? `● ĐANG PHÂN TÍCH ${comparisonKey.toUpperCase()} ${comparisonLocked?'· ĐÃ GHIM':'· ĐANG XEM'}` : '● RÊ CHUỘT HOẶC CHẠM VÀO PHƯƠNG ÁN ĐỂ XEM PHÂN TÍCH') + (matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.documentElement.classList.contains('rig-force-motion')?' · HỆ THỐNG ĐANG GIẢM CHUYỂN ĐỘNG':'');}
    const panel=shell.querySelector('[data-compare-reveal]');
    panel.setAttribute('aria-hidden',String(!isOpen));panel.inert=!isOpen;
    const content=shell.querySelector('[data-compare-content]');
    if(isOpen){const p=activePresets().find(p=>p.key===comparisonKey);if(p){content.innerHTML=comparisonMarkup(p);content.querySelector('[data-close-comparison]')?.addEventListener('click',()=>closeComparison());content.querySelector('[data-apply]')?.addEventListener('click',()=>applyPreset(p.key));content.querySelector('[data-open-full-compare]')?.addEventListener('click',()=>setPage('compare'));}}
    else{content.innerHTML='';}
  }
  function openComparison(key,lock=false){clearTimeout(comparisonExitTimer);comparisonKey=key;if(lock)comparisonLocked=true;updateComparisonUI();}
  function closeComparison(){clearTimeout(comparisonExitTimer);comparisonKey=null;comparisonLocked=false;updateComparisonUI();}
  function applyPreset(key){const p=activePresets().find(x=>x.key===key);if(!p)return;
    if(colorPolicy==='strict'&&desiredColor()){
      const r=colorReview(p.items);
      if(r.unknown.length||r.mismatch.length){showToast('Chưa áp dụng: có '+(r.unknown.length+r.mismatch.length)+' món chưa xác nhận đúng màu. Chọn Ưu tiên màu để tiếp tục.');return;}
    }
    selected=normalize(p.items).items;comparisonKey=null;comparisonLocked=false;setPage('build');showToast('Đã áp dụng '+p.name);}
  function bindComparisonEvents(){
    const shell=document.querySelector('[data-compare-stage]');if(!shell)return;
    // Attach to cards themselves, NOT a pointer: fine media query. Hybrid laptops work.
    shell.querySelectorAll('[data-option]').forEach(card=>{
      const preview=(event)=>{
        if(event?.pointerType==='touch'||comparisonLocked)return;
        if(comparisonKey!==card.dataset.option)openComparison(card.dataset.option);
      };
      card.addEventListener('pointerenter',preview);
      card.addEventListener('mouseenter',preview); // classic mouse fallback
      card.addEventListener('focusin',preview);
      card.addEventListener('click',event=>{
        if(event.target.closest('[data-apply]'))return;
        openComparison(card.dataset.option,true);
      });
    });
    shell.addEventListener('pointerenter',()=>clearTimeout(comparisonExitTimer));
    shell.addEventListener('pointerleave',()=>{if(!comparisonLocked)comparisonExitTimer=setTimeout(()=>closeComparison(),320);});
    updateComparisonUI();
  }
  function optionCards(){return `<section class="compare-stage" data-compare-stage aria-label="Ba phương án cấu hình và so sánh tương tác"><div class="options-header"><div><div class="kicker">// SO SÁNH & TỐI ƯU</div><h2>3 PHƯƠNG ÁN THAM KHẢO</h2></div></div><p class="compare-hint"><span class="pulse"></span><span><strong>Rê chuột</strong> vào một phương án để xem phân tích bên dưới. <strong>Nhấn</strong> để giữ bảng mở; trên điện thoại, chỉ cần chạm.</span></p><div class="option-grid">${activePresets().map((p,i)=>{const sum=priceOf(p.items);return `<article class="option ${i===1?'featured':''}" data-option="${p.key}">${i===1?'<span class="sticker">GỢI Ý</span>':''}<button class="option-focus" type="button" data-compare="${p.key}" aria-pressed="false" aria-label="Xem phân tích ${esc(p.name)} so với cấu hình hiện tại"><div class="option-label">${p.type}</div><h3>${p.name}</h3><div class="option-price">${estimateLabel(sum)}</div><p>${p.description}</p><div class="option-color-status">◐ ${esc(colorSummary(p.items))}</div><div class="specs"><span>◈ ${esc(partOf('cpu',p.items).name)}</span><span>◈ ${esc(partOf('gpu',p.items).name)}</span><span style="color:${sum==null?'#9fb3c4':sum>budget?'#ff9ca4':'#a8e6a9'}">${sum==null?'? Chưa đủ dữ liệu giá':sum>budget?'↑ Ước tính vượt ngân sách':'✓ Ước tính trong ngân sách'}</span></div><div class="compare-cta"><span>↗</span> XEM SO SÁNH & PHÂN TÍCH</div></button><button class="btn ${i===1?'primary':''}" data-apply="${p.key}" ${colorPolicy==='strict'&&desiredColor()&&(colorReview(p.items).mismatch.length||colorReview(p.items).unknown.length)?'disabled title="Chưa đủ dữ liệu màu"':''}>ÁP DỤNG CẤU HÌNH ↗</button></article>`;}).join('')}</div><div class="compare-reveal" data-compare-reveal aria-hidden="true" inert><div class="compare-reveal-clip"><div class="compare-reveal-inner" data-compare-content></div></div></div></section>`;}
  function renderBuild(){const status=assessment();return `<div class="layout" id="workspace"><section class="section"><div class="section-head"><div><div class="kicker">// LỰA CHỌN LINH KIỆN</div><h2>Cấu hình bạn đang chọn</h2></div><div class="micro">08 / 08 LINH KIỆN</div></div>${budgetPanel()}${colorPanel()}<div class="build-instruction"><span class="seq">01 CPU → 02 MAIN → 03 RAM</span><span>Chọn theo thứ tự. Khi đổi CPU hoặc mainboard, hệ thống sẽ điều chỉnh các lựa chọn không còn tương thích.</span></div><div class="parts">${categories.map((c,i)=>{const current=partOf(c.id),choices=sortedColorChoices(c.id,compatibleOptions(c.id,selected));return `<div class="part"><div class="part-ico">${c.short}</div><div class="component-control"><div class="part-name">${esc(c.label)} <span class="match-count">${choices.length}/${parts[c.id].length} phù hợp</span></div><input class="part-search" data-part-search="${c.id}" type="search" placeholder="Lọc nhanh ${esc(c.short)} (${choices.length} lựa chọn)..." autocomplete="off" aria-label="Lọc linh kiện ${esc(c.short)}"><select data-part="${c.id}" aria-label="Chọn ${esc(c.label)}">${choices.map(p=>`<option value="${p.id}" ${p.id===selected[c.id]?'selected':''}>${esc(p.name)}${desiredColor()&&visibleColorCategories.includes(c.id)?' • '+colorText(c.id,p):''}</option>`).join('')}</select><span class="part-hint">${esc(c.hint)}${desiredColor()&&visibleColorCategories.includes(c.id)?` • ${colorText(c.id,current)}`:""}</span></div><div class="part-price"><strong>${estimateLabel(current.price)}</strong><small>${priceDescriptor(current)}</small>${linkBelowPrice(current)}</div></div>`}).join('')}</div><div class="section-foot"><div class="footnote"><strong>Lưu ý:</strong> Giá chưa xác minh là dữ liệu minh họa; một số mẫu linh kiện, kích thước GPU/case và khả năng tải tản nhiệt là dữ liệu mô phỏng. Kiểm tra thông số chính hãng, BIOS, đầu nguồn và kích thước trước khi mua. Đường dẫn sản phẩm không bảo đảm cửa hàng còn hàng.</div><div><button class="btn ghost" id="resetBtn">ĐẶT LẠI</button> <button class="btn primary" id="saveBtn">LƯU CẤU HÌNH ↗</button></div></div></section><aside class="section inspector"><div class="kicker">ĐÁNH GIÁ SƠ BỘ //</div><h3>Kiểm tra tương thích cơ bản</h3><div class="score-ring" style="--progress:${status.score}"><div class="score-inner"><strong>${status.score}</strong><span>/ 100 ĐIỂM KIỂM TRA</span></div></div><div class="rating">${status.errors>0?'⚠ CẦN KIỂM TRA LẠI':status.pending?'◌ CÒN THÔNG SỐ CẦN XÁC MINH':'✓ CHƯA PHÁT HIỆN LỖI THEO DỮ LIỆU CÓ SẴN'}</div><div class="checklist">${status.messages.map(m=>`<div class="check ${m.ok===false?'warn':m.ok===null?'pending':''}"><span class="check-icon">${m.ok===null?'?':m.ok?'✓':'!'}</span><span>${esc(m.label)}</span></div>`).join('')}</div><div class="color-inspector"><div class="kicker">◐ COLOR MATCH</div><strong>${esc(colorSummary(selected))}</strong>${desiredColor()&&colorReview(selected).mismatch.length?`<small class="color-alert">Khác màu: ${colorReview(selected).mismatch.map(c=>c.toUpperCase()).join(", ")}</small>`:""}${desiredColor()&&colorReview(selected).unknown.length?`<small>Chưa xác minh: ${colorReview(selected).unknown.map(c=>c.toUpperCase()).join(", ")}</small>`:""}</div><div class="total"><label>TỔNG CHI PHÍ ƯỚC TÍNH</label><strong>${estimateLabel(priceOf(selected))}</strong></div></aside></div>${optionCards()}`;}
  /* -------------------------------------------------------------
     Smart Consultation — independent multi-answer questionnaire
     All answers are opt-in. Suggestions remain rule-based previews.
     ------------------------------------------------------------- */
  const advisorConfig = window.NEON_ADVISOR_CONFIG;
  const advisorSaved = (()=>{try{return JSON.parse(localStorage.getItem('neon-rig-advisor-v11')||'{}')}catch{return {}}})();
  let advisorNeeds = new Set(Array.isArray(advisorSaved.needs)?advisorSaved.needs:[]);
  let advisorAnswers = advisorSaved.answers && typeof advisorSaved.answers==='object' ? advisorSaved.answers : {};
  let advisorPriorities = advisorSaved.priorities && typeof advisorSaved.priorities==='object' ? advisorSaved.priorities : {};
  let advisorExpanded = new Set(['gaming',...advisorConfig.groups.filter(g=>g.needs.some(n=>advisorNeeds.has(n.id))).map(g=>g.id)]);
  let advisorGenerated = false;
  let advisorProposals = [];
  const advisorSave = () => {try{localStorage.setItem('neon-rig-advisor-v11',JSON.stringify({needs:[...advisorNeeds],answers:advisorAnswers,priorities:advisorPriorities}));}catch{} };
  const advisorSelectedGroups = () => advisorConfig.groups.filter(g=>g.needs.some(n=>advisorNeeds.has(n.id)));
  const advisorQuestions = group => group.questions.filter(q=>!q.when.length||q.when.some(n=>advisorNeeds.has(n)));
  const advisorQuestionCount = () => advisorSelectedGroups().reduce((n,g)=>n+advisorQuestions(g).length,0);
  const advisorQuestionAnswered = () => advisorSelectedGroups().reduce((n,g)=>n+advisorQuestions(g).filter(q=>Array.isArray(advisorAnswers[q.id])&&advisorAnswers[q.id].length>0).length,0);
  const advisorHas = id => advisorNeeds.has(id);
  const advisorSelectedAnswer = (questionId,value) => Array.isArray(advisorAnswers[questionId]) && advisorAnswers[questionId].includes(value);
  function advisorNeedsMarkup(){
    return advisorConfig.groups.map(g=>{
      const count=g.needs.filter(n=>advisorHas(n.id)).length;
      return `<details class="advisor-group" data-advisor-group="${g.id}" ${advisorExpanded.has(g.id)?'open':''}>
        <summary><span class="advisor-group-icon">${g.icon}</span><span class="advisor-group-title"><strong>${esc(g.title)}</strong><small>${esc(g.hint)}</small></span><span class="advisor-group-count ${count?'chosen':''}">${count}/${g.needs.length} đã chọn</span><span class="advisor-chevron">⌄</span></summary>
        <div class="advisor-need-grid">${g.needs.map(n=>`<label class="advisor-check ${advisorHas(n.id)?'checked':''}"><input type="checkbox" data-advisor-need="${n.id}" ${advisorHas(n.id)?'checked':''}><span class="advisor-check-indicator">✓</span><span>${esc(n.label)}</span></label>`).join('')}</div>
        ${count?`<div class="advisor-priority"><label for="priority-${g.id}">Mức ưu tiên nhóm này</label><select id="priority-${g.id}" data-advisor-priority="${g.id}"><option value="high" ${(advisorPriorities[g.id]||'high')==='high'?'selected':''}>Rất quan trọng</option><option value="normal" ${advisorPriorities[g.id]==='normal'?'selected':''}>Bình thường</option><option value="low" ${advisorPriorities[g.id]==='low'?'selected':''}>Phụ / ít dùng</option></select></div>`:''}
      </details>`;
    }).join('');
  }
  function advisorDetailsMarkup(){
    const active=advisorSelectedGroups();
    if(!active.length)return `<div class="advisor-empty">Hãy chọn ít nhất một nhu cầu phía trên. Những câu hỏi liên quan sẽ xuất hiện ở đây.</div>`;
    return active.map(group=>`<div class="advisor-question-group"><div class="advisor-question-group-head"><strong>${esc(group.title)}</strong><span>${advisorQuestions(group).length} câu hỏi • Có thể chọn nhiều đáp án</span></div>
      ${advisorQuestions(group).map(q=>`<fieldset class="advisor-question"><legend>${esc(q.title)}</legend><div class="advisor-answer-grid">${q.options.map(o=>`<label class="advisor-answer ${advisorSelectedAnswer(q.id,o)?'checked':''}"><input type="checkbox" data-advisor-answer="${q.id}" value="${esc(o)}" ${advisorSelectedAnswer(q.id,o)?'checked':''}><span class="advisor-answer-box">✓</span><span>${esc(o)}</span></label>`).join('')}</div></fieldset>`).join('')}
    </div>`).join('');
  }
  function advisorSignals(){
    const g=advisorSelectedGroups();
    const weight=id=>{const selectedGroup=g.find(x=>x.id===id);if(!selectedGroup)return 0;return {high:2,normal:1,low:.45}[advisorPriorities[id]||'high'];};
    // Only active questions for currently selected needs may affect recommendations.
    // Previously, deselected groups could leave hidden answers influencing the build.
    const answers=g.flatMap(group=>advisorQuestions(group).flatMap(q=>Array.isArray(advisorAnswers[q.id])?advisorAnswers[q.id]:[]));
    const chosen=new Set(answers);
    const gpu=1+weight('gaming')*1.2+weight('creative')*.85+weight('engineering')*.65+weight('ai')*1.3+weight('stream')*.35;
    const cpu=1+weight('dev')*.9+weight('engineering')*.9+weight('server')*1.2+weight('stream')*.75+weight('ai')*.7+weight('creative')*.55;
    const needsHighRam=advisorHas('gaming-4')||advisorHas('engineering-2')||advisorHas('dev-4')||advisorHas('dev-5')||advisorHas('ai-4')||advisorHas('server-4')||chosen.has('150–300+ mod')||chosen.has('4K')||chosen.has('6K / 8K');
    return {cpu,gpu,minRam:needsHighRam?32:16,wantStorage:chosen.has('4K')||chosen.has('6K / 8K')||chosen.has('Nhiều lớp hiệu ứng / RAW')||advisorHas('server-1')?2000:1000,chosen};
  }
  // This is a constrained *demonstration* search over products with example
  // prices, not FPS forecasting or a claim of professional PC validation.
  function advisorGenerateBuilds(){
    const signal=advisorSignals(),candidates=[];
    const valid=id=>parts[id].filter(isPriced);
    const CPUs=valid('cpu'),boards=valid('board'),rams=valid('ram'),gpus=valid('gpu'),ssds=valid('ssd'),coolers=valid('cooler'),cases=valid('case'),psus=valid('psu');
    const cpuRank={r5:1,i5:2,r7:3},gpuRank={'5060ti':1,'5070':2,'5070ti':3};
    for(const cpu of CPUs)for(const board of boards){
      if(cpu.socket!==board.socket)continue;
      for(const ram of rams){if(ram.ram!==board.ram)continue;
        for(const gpu of gpus)for(const ssd of ssds)for(const cooler of coolers){
          if(!cooler.sockets?.includes(cpu.socket)||cooler.cap!=null&&cooler.cap<cpu.watts)continue;
          for(const cs of cases){
            if(!cs.forms?.includes(board.form)||cs.maxGpu!=null&&gpu.gpuLength!=null&&gpu.gpuLength>cs.maxGpu||cs.maxRad!=null&&cooler.rad>cs.maxRad||cs.maxAir!=null&&cooler.coolerHeight>cs.maxAir)continue;
            for(const psu of psus){
              const items={cpu:cpu.id,board:board.id,ram:ram.id,gpu:gpu.id,ssd:ssd.id,cooler:cooler.id,case:cs.id,psu:psu.id};
              if(psu.watts<requiredPSU(items))continue;
              const price=cpu.price+board.price+ram.price+gpu.price+ssd.price+cooler.price+cs.price+psu.price;
              if(price>budget)continue;
              const col=colorReview(items);
              if(colorPolicy==='strict'&&desiredColor()&&(col.mismatch.length||col.unknown.length))continue;
              const ramGB=ram.capacity||(/32GB/.test(ram.name)?32:16);
              const storageGB=ssd.capacity||(/2TB/.test(ssd.name)?2000:1000);
              const raw=signal.cpu*(cpuRank[cpu.id]||1)+signal.gpu*(gpuRank[gpu.id]||1)+ (ramGB>=signal.minRam?1.1:-1.4) + (storageGB>=signal.wantStorage?0.6:0) + (board.ram==='DDR5'?.18:0);
              const colorPenalty=desiredColor()?col.mismatch.length*.8+col.unknown.length*.18:0;
              candidates.push({items,price,quality:raw-colorPenalty,ramGB,storageGB,mismatch:col.mismatch.length,unknown:col.unknown.length});
            }
          }
        }
      }
    }
    if(!candidates.length)return [];
    // Prices must ascend: economical < balanced < high-end.
    // A pricier part is not automatically a performance improvement; premium
    // only uses more budget where the metadata yields a meaningful upgrade.
    const cheapest=[...candidates].sort((a,b)=>a.price-b.price||b.quality-a.quality)[0];
    const premium=[...candidates].sort((a,b)=>b.quality-a.quality||b.price-a.price)
      .find(x=>x.price>cheapest.price+2000000) || null;
    if(!premium)return [cheapest];
    const lower=cheapest.price+1200000,upper=premium.price-1200000;
    const midpoint=cheapest.price+(premium.price-cheapest.price)*.53;
    const middle=[...candidates]
      .filter(x=>x.price>=lower&&x.price<=upper&&x.quality>=cheapest.quality)
      .sort((a,b)=>{
        const as=a.quality*.6-Math.abs(a.price-midpoint)/1000000*.85;
        const bs=b.quality*.6-Math.abs(b.price-midpoint)/1000000*.85;
        return bs-as||a.price-b.price;
      })[0];
    return middle?[cheapest,middle,premium]:[cheapest,premium];
  }
  function advisorTier(index){
    if(advisorProposals.length===1)return {key:'value',label:'01 / THAM KHẢO',title:'SMART VALUE'};
    if(advisorProposals.length===2)return index===0?{key:'value',label:'01 / TIẾT KIỆM',title:'SMART VALUE'}:{key:'premium',label:'02 / HIỆU NĂNG',title:'POWER BUILD'};
    return [
      {key:'value',label:'01 / TIẾT KIỆM',title:'SMART VALUE'},
      {key:'balanced',label:'02 / CÂN BẰNG',title:'SWEET SPOT'},
      {key:'premium',label:'03 / HIỆU NĂNG',title:'POWER BUILD'}
    ][index];
  }
  function advisorExplain(index){
    const build=advisorProposals[index];if(!build)return null;
    const items=build.items;
    const components=Object.fromEntries(categories.map(c=>[c.id,partOf(c.id,items)]));
    return window.NEON_ADVISOR_EXPLAIN.evaluate({
      groups:advisorConfig.groups,needs:advisorNeeds,answers:advisorAnswers,priorities:advisorPriorities,
      parts:components,price:build.price,budget,tier:advisorTier(index).key,
      signal:advisorSignals(),colorMode,colorReview:colorReview(items)
    });
  }
  function advisorResultCard(build,index){
    const tier=advisorTier(index),info=advisorExplain(index);
    const items=build.items,inspection=assessment(items);
    const warnings=[];
    if(inspection.errors)warnings.push(`${inspection.errors} kiểm tra kỹ thuật sơ bộ cần xem lại.`);
    for(const issue of info.groupResults.filter(g=>g.status==='warning').slice(0,2))warnings.push(issue.note);
    const reasons=info.facts.slice(0,2);
    return `<article class="advisor-result-card" data-advisor-option="${index}" tabindex="0" role="group" aria-label="Phương án ${esc(tier.label)}"><div class="advisor-result-top"><span class="advisor-tag">${esc(tier.label)}</span><span class="advisor-result-price">${estimateLabel(build.price)}</span></div><h3>${tier.title}</h3>
      <p class="advisor-card-overview">${esc(info.recommendation)}</p>
      <div class="advisor-card-context"><span>↗ ĐỐI CHIẾU HỒ SƠ</span><strong>${esc(info.signature)}</strong></div>
      <div class="advisor-quick-spec"><span><b>CPU</b>${esc(partOf('cpu',items).name)}</span><span><b>GPU</b>${esc(partOf('gpu',items).name)}</span><span><b>RAM</b>${esc(partOf('ram',items).name)}</span></div>
      <div class="advisor-mini-rationale"><strong>VÌ SAO ĐỀ XUẤT?</strong>${reasons.map(r=>`<p><b>${esc(r.heading)}:</b> ${esc(r.body)}</p>`).join('')}</div>
      ${warnings.length?`<div class="advisor-warning">${warnings.map(w=>`<div>⚠ ${esc(w)}</div>`).join('')}</div>`:''}
      <details class="advisor-result-details"><summary>Xem đủ 8 linh kiện <span>⌄</span></summary><div>${categories.map(c=>`<div class="advisor-detail-line"><b>${esc(c.short)}</b><span>${esc(partOf(c.id,items).name)}</span></div>`).join('')}</div></details>
      <button type="button" class="advisor-compare-button" data-advisor-open="${index}" aria-expanded="false">◈ XEM LÝ DO & MỨC PHÙ HỢP</button>
      <button class="btn ${index===1?'primary':'ghost'}" data-advisor-apply="${index}" type="button">CHỈNH SỬA CẤU HÌNH NÀY ↗</button></article>`;
  }
  function advisorResultsMarkup(){
    if(!advisorGenerated)return '';
    if(!advisorProposals.length)return `<section class="advisor-results-section" id="advisorGenerated" data-advisor-results><div class="advisor-result-head"><div class="kicker">// ADVISOR OUTPUT</div><h2>Chưa đủ dữ liệu giá để tạo phương án phù hợp</h2><p>Không tìm thấy bộ PC có đủ giá mẫu, tương thích sơ bộ và không vượt ${estimateLabel(budget)}${colorPolicy==='strict'&&desiredColor()?' với yêu cầu bắt buộc đúng màu':''}. Hãy thử ngân sách khác hoặc thay đổi điều kiện. Hệ thống không tự tạo giá cho linh kiện chưa có dữ liệu.</p></div></section>`;
    const selectedLabels=advisorConfig.groups.flatMap(g=>g.needs.filter(n=>advisorNeeds.has(n.id)).map(n=>n.label));
    return `<section class="advisor-results-section" id="advisorGenerated" data-advisor-results><div class="advisor-result-head"><div><div class="kicker">// SMART CONSULTATION / RULE-BASED PREVIEW</div><h2>${advisorProposals.length} cấu hình theo câu trả lời của bạn</h2><p>Dựa trên ${advisorNeeds.size} nhu cầu và ${advisorQuestionAnswered()} câu hỏi đã trả lời; ngân sách ${estimateLabel(budget)}. Đây là đề xuất sơ bộ từ các linh kiện <b>có giá demo</b>, chưa phải tối ưu thị trường hoặc benchmark.</p></div><button class="btn ghost" id="advisorEdit">SỬA CÂU TRẢ LỜI</button></div>
      <div class="advisor-chosen-pills">${selectedLabels.slice(0,12).map(t=>`<span>${esc(t)}</span>`).join('')}${selectedLabels.length>12?`<span>+${selectedLabels.length-12} mục khác</span>`:''}</div>
      <div class="advisor-motion-top"><span class="motion-status" data-advisor-motion-status>● RÊ CHUỘT HOẶC CHẠM VÀO PHƯƠNG ÁN ĐỂ XEM PHÂN TÍCH</span></div>
      <div class="advisor-results-grid">${advisorProposals.map(advisorResultCard).join('')}</div>
      <div class="advisor-compare-panel" data-advisor-compare-panel aria-hidden="true" inert><div class="advisor-compare-clip"><div class="advisor-compare-body" data-advisor-compare-body></div></div></div>
      <div class="advisor-disclaimer">Giá đang là mức tham khảo, trong đó có các mẫu dùng dữ liệu minh họa; kho sản phẩm chưa có đủ báo giá. Chưa có dữ liệu benchmark/FPS. Khi mua cần xác minh BIOS, đầu nguồn GPU, kích thước và màu từng phiên bản.</div>
      </section>`;
  }
  // Advisor generated cards are separate from the preset card markup.
  // Keep the hover/pin motion, but assess answers, NOT Self Build.
  function advisorComparisonMarkup(index){
    const build=advisorProposals[index];if(!build)return '';
    const info=advisorExplain(index),tier=advisorTier(index);
    const amount=Number.isFinite(build.price)?build.price:0;
    const pct=budget>0?Math.max(0,Math.min(100,amount/budget*100)):0;
    const remaining=Number.isFinite(build.price)?budget-build.price:null;
    const statusLabel={warning:'CẦN ĐIỀU CHỈNH',verify:'CẦN XÁC MINH',partial:'ĐẠT TIÊU CHÍ SƠ BỘ'};
    const overview=info.groupResults.map(g=>`<div class="advisor-fit-row ${g.status}">
        <div class="advisor-fit-heading"><h5>${esc(g.title)}</h5><span class="advisor-fit-status ${g.status}">${statusLabel[g.status]}</span></div>
        <div class="advisor-fit-priority">Mức ưu tiên: ${esc(({high:'Cốt lõi',normal:'Bình thường',low:'Phụ'})[g.priority]||'Cốt lõi')}</div>
        <div class="advisor-fit-needs">${g.labels.slice(0,3).map(x=>`<span>${esc(x)}</span>`).join('')}${g.labels.length>3?`<span>+${g.labels.length-3} nhu cầu</span>`:''}</div>
        ${g.answers.length?`<p class="advisor-fit-answers"><b>Bạn đã chọn:</b> ${esc(g.answers.map(a=>a.value).slice(0,7).join(' • '))}${g.answers.length>7?` • +${g.answers.length-7} đáp án`:''}</p>`:''}
        <p class="advisor-fit-note">${esc(g.note)}</p>
      </div>`).join('');
    return `<div class="advisor-eval-head"><div><div class="kicker">◈ SMART ADVISOR / NEEDS ANALYSIS</div><h3>${esc(tier.title)} <span>—</span> VÌ SAO PHÙ HỢP?</h3><p>Đánh giá phương án này theo <strong>câu trả lời và mức ưu tiên bạn đã nhập</strong>, không so với cấu hình ở trang Tự Build.</p></div><button class="compare-close" type="button" data-advisor-close>✕ ĐÓNG</button></div>
      <div class="advisor-eval-budget">
        <div><span>NGÂN SÁCH CỦA BẠN</span><b>${estimateLabel(budget)}</b></div>
        <div><span>GIÁ PHƯƠNG ÁN</span><b class="lime">${estimateLabel(build.price)}</b></div>
        <div><span>${remaining!==null&&remaining>=0?'NGÂN SÁCH CÒN LẠI':'CHÊNH LỆCH NGÂN SÁCH'}</span><b>${remaining===null?'Chưa đủ dữ liệu giá':estimateLabel(Math.abs(remaining))}</b></div>
        <div class="advisor-eval-track" aria-label="Đã sử dụng khoảng ${Math.round(pct)} phần trăm ngân sách"><span style="width:${pct.toFixed(2)}%"></span></div>
      </div>
      <div class="advisor-eval-section"><div class="advisor-eval-section-head"><h4>01 / Lý do chọn linh kiện</h4><small>GIẢI THÍCH THEO NHU CẦU</small></div>
        <div class="advisor-reason-grid">${info.facts.map(f=>`<div class="advisor-reason"><b>${esc(f.heading)}</b><p>${esc(f.body)}</p></div>`).join('')}</div>
      </div>
      <div class="advisor-eval-section"><div class="advisor-eval-section-head"><h4>02 / Đối chiếu từng nhóm nhu cầu</h4><small>${info.groupResults.length} NHÓM/TIÊU CHÍ</small></div>
        <div class="advisor-fit-grid">${overview}</div>
      </div>
      <div class="advisor-eval-section"><div class="advisor-eval-section-head"><h4>03 / Điểm cần cân nhắc và lời khuyên</h4><small>KHÔNG ĐOÁN FPS</small></div>
        <div class="advisor-conclusion"><div class="advisor-conclusion-notes">${info.notes.map(n=>`<p>◈ ${esc(n)}</p>`).join('')}</div><div class="advisor-conclusion-verdict"><span>DEXORA KHUYÊN</span><p>${esc(info.recommendation)}</p></div></div>
      </div>
      <p class="advisor-explain-disclaimer">Chỉ đối chiếu thông số đã có, bộ quy tắc lựa chọn và giá ước tính/demo. Nhãn “đạt tiêu chí sơ bộ” không có nghĩa chắc chắn đủ FPS, tốc độ render, nhiệt độ hoặc độ ổn định. Nên xác minh SKU, BIOS, kích thước, công suất và benchmark trước khi mua.</p>
      <div class="compare-actions-bottom"><button class="btn primary" data-advisor-pick="${index}">CHỈNH SỬA PHƯƠNG ÁN NÀY ↗</button></div>`;
  }
  function updateAdvisorComparison(){
    const shell=document.querySelector('[data-advisor-results]'); if(!shell)return;
    const isOpen=Number.isInteger(advisorComparisonIndex)&&!!advisorProposals[advisorComparisonIndex];
    shell.querySelectorAll('[data-advisor-option]').forEach(card=>{
      card.classList.toggle('rig-active',isOpen&&Number(card.dataset.advisorOption)===advisorComparisonIndex);
      card.classList.toggle('rig-dimmed',isOpen&&Number(card.dataset.advisorOption)!==advisorComparisonIndex);
    });
    shell.querySelectorAll('[data-advisor-open]').forEach(btn=>btn.setAttribute('aria-expanded',String(isOpen&&Number(btn.dataset.advisorOpen)===advisorComparisonIndex)));
    const stat=shell.querySelector('[data-advisor-motion-status]');
    if(stat)stat.textContent=(isOpen?`● ĐANG PHÂN TÍCH PHƯƠNG ÁN ${advisorComparisonIndex+1} ${advisorComparisonLocked?'· ĐÃ GHIM':'· ĐANG XEM'}`:'● RÊ CHUỘT HOẶC CHẠM VÀO PHƯƠNG ÁN ĐỂ XEM PHÂN TÍCH') + (matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.documentElement.classList.contains('rig-force-motion')?' · HỆ THỐNG ĐANG GIẢM CHUYỂN ĐỘNG':'');
    const panel=shell.querySelector('[data-advisor-compare-panel]');if(!panel)return;
    panel.classList.toggle('is-open',isOpen);panel.setAttribute('aria-hidden',String(!isOpen));panel.inert=!isOpen;
    const content=shell.querySelector('[data-advisor-compare-body]');
    if(!content)return;
    if(isOpen){content.innerHTML=advisorComparisonMarkup(advisorComparisonIndex);
      content.querySelector('[data-advisor-close]')?.addEventListener('click',()=>closeAdvisorComparison());
      content.querySelector('[data-advisor-pick]')?.addEventListener('click',()=>applyAdvisorProposal(advisorComparisonIndex));
    }else content.innerHTML='';
  }
  function openAdvisorComparison(index,lock=false){
    clearTimeout(advisorComparisonExitTimer);
    advisorComparisonIndex=index;if(lock)advisorComparisonLocked=true;
    updateAdvisorComparison();
  }
  function closeAdvisorComparison(){
    clearTimeout(advisorComparisonExitTimer);advisorComparisonIndex=null;advisorComparisonLocked=false;
    updateAdvisorComparison();
  }
  function applyAdvisorProposal(index){
    const p=advisorProposals[index]; if(!p)return;
    selected=normalize(p.items).items;advisorComparisonIndex=null;advisorComparisonLocked=false;
    setPage('build');showToast('Đã đưa cấu hình tư vấn sang Tự Build để chỉnh sửa và kiểm tra');
  }
  function bindAdvisorComparison(){
    const shell=document.querySelector('[data-advisor-results]'); if(!shell)return;
    shell.querySelectorAll('[data-advisor-option]').forEach(card=>{
      const preview=(event)=>{
        if(event?.pointerType==='touch'||advisorComparisonLocked)return;
        const index=Number(card.dataset.advisorOption);
        if(advisorComparisonIndex!==index)openAdvisorComparison(index);
      };
      card.addEventListener('pointerenter',preview);
      card.addEventListener('mouseenter',preview);
      card.addEventListener('focusin',preview);
      card.addEventListener('click',event=>{
        if(event.target.closest('[data-advisor-apply], details, summary'))return;
        openAdvisorComparison(Number(card.dataset.advisorOption),true);
      });
    });
    shell.addEventListener('pointerenter',()=>clearTimeout(advisorComparisonExitTimer));
    shell.addEventListener('pointerleave',()=>{if(!advisorComparisonLocked)advisorComparisonExitTimer=setTimeout(()=>closeAdvisorComparison(),320);});
    updateAdvisorComparison();
  }
  function renderAdvisor(){
    const count=advisorNeeds.size,answered=advisorQuestionAnswered(),total=advisorQuestionCount();
    return `<section class="section advisor-page"><div class="page-intro"><div class="kicker">// DEXORA • SMART CONSULTATION</div><h2>Có thể chọn nhiều nhu cầu cùng lúc.</h2><p>Chọn nhiều nhu cầu và <strong>nhiều đáp án trong cùng một câu hỏi</strong>. Hệ thống kết hợp tất cả câu trả lời, rồi mới đưa ra ba phương án tham khảo.</p></div>
      <div class="advisor-guide"><span>01 <b>Ngân sách & màu</b></span><span>02 <b>Chọn nhiều nhu cầu</b></span><span>03 <b>Trả lời chi tiết</b></span><span>04 <b>Nhận cấu hình</b></span></div>
      <div class="advisor-upper">${budgetPanel()}${colorPanel()}</div>
      <div class="advisor-section-head"><div><div class="kicker">// STEP 02 / MULTI-SELECT</div><h3>Nhu cầu sử dụng</h3><p>Chọn bao nhiêu mục cũng được, kể cả thuộc những nhóm khác nhau.</p></div><span class="advisor-total-selected">${count} / ${advisorConfig.totalNeeds} nhu cầu</span></div>
      <div class="advisor-category-grid">${advisorNeedsMarkup()}</div>
      <div class="advisor-section-head advisor-questions-head"><div><div class="kicker">// STEP 03 / SMART QUESTIONS</div><h3>Câu hỏi chuyên sâu</h3><p>Mỗi câu có thể chọn nhiều đáp án. Không biết thì để trống; câu hỏi sẽ xuất hiện tùy nhu cầu đã chọn.</p></div><span class="advisor-total-selected">${answered} / ${total} đã trả lời</span></div>
      <div class="advisor-questions">${advisorDetailsMarkup()}</div>
      <div class="advisor-submit"><div><strong>Đã chọn xong nhu cầu?</strong><p>${count?`${count} nhu cầu được chọn • ${answered}/${total} câu hỏi đã trả lời. Có thể bỏ qua câu hỏi chưa rõ.`:'Chọn ít nhất một nhu cầu để tiếp tục.'}</p></div><div class="advisor-submit-actions"><button class="btn ghost" type="button" id="advisorClear">XÓA CÂU TRẢ LỜI</button><button class="btn primary" type="button" id="advisorGenerate" ${count?'':'disabled'}>XEM 3 CẤU HÌNH PHÙ HỢP ↗</button></div></div></section>
      ${advisorResultsMarkup()}`;
  }
  const filteredCatalog = () => categories.flatMap(c=>parts[c.id].map(p=>({...p,category:c.short,group:c.id}))).filter(p=>(catalogFilter==='all'||p.group===catalogFilter)&&(p.name+' '+(p.brand||'')+' '+(p.sku||'')+' '+(p.color||'')).toLowerCase().includes(catalogQuery.toLowerCase()));
  function catalogHTML(){return filteredCatalog().map(p=>`<div class="catalog-item"><div class="category">[ ${esc(p.category)} ]</div><h3>${esc(p.name)}</h3><div class="code">${p.brand?esc(p.brand)+' • ':''}${p.color?esc(colorName[p.color]||p.color)+' • ':''} ID: ${esc(p.id.toUpperCase())}</div><div class="cost">${estimateLabel(p.price)}</div><div class="catalog-estimate">${priceDescriptor(p)}</div>${linkBelowPrice(p)}</div>`).join('')||'<p>Không tìm thấy linh kiện phù hợp.</p>';}
  function renderCatalog(){return `<section class="section page-alt"><div class="page-intro"><div class="kicker">// GLOBAL COMPONENT LIBRARY</div><h2>Kho linh kiện mở rộng</h2><p>Danh mục hiện có ${catalogCount()} linh kiện/dòng sản phẩm, kể cả mẫu chưa có giá hay link mua. Đây chưa phải toàn bộ SKU trên thế giới. Toàn bộ sản phẩm đều có thể tìm thấy, <strong>không bị ẩn theo tỉnh hay cửa hàng</strong>. Link chỉ hiện khi đúng sản phẩm đã có URL tại cửa hàng chọn.</p></div><div class="catalog-toolbar"><input class="field" id="catalogSearch" placeholder="Tìm model, hãng, màu sắc..." value="${esc(catalogQuery)}"><select id="catalogFilter" class="field" style="max-width:160px"><option value="all">Tất cả</option>${categories.map(c=>`<option value="${c.id}" ${catalogFilter===c.id?'selected':''}>${c.short}</option>`).join('')}</select></div><div id="catalogItems" class="catalog-items">${catalogHTML()}</div></section>`;}
  function renderCompare(){const presets=activePresets();return `<section class="section page-alt"><div class="page-intro"><div class="kicker">// SO SÁNH CẤU HÌNH</div><h2>So sánh cấu hình đang chọn và 3 phương án tham khảo</h2><p>Giá là ước tính từ nguồn cửa hàng đã xác minh nếu có; linh kiện chưa cập nhật vẫn là giá demo. Đây không phải báo giá chính thức hay dữ liệu FPS đã đo.</p></div>${optionCards()}<div class="compare-table"><table><thead><tr><th>THÀNH PHẦN</th><th>CẤU HÌNH CỦA BẠN</th>${presets.map(p=>`<th>${p.name}</th>`).join('')}</tr></thead><tbody>${categories.map(c=>`<tr><td>${c.short}</td><td>${esc(partOf(c.id).name)}</td>${presets.map(p=>`<td>${esc(partOf(c.id,p.items).name)}</td>`).join('')}</tr>`).join('')}<tr><td><strong>TỔNG GIÁ</strong></td><td><strong>${estimateLabel(priceOf(selected))}</strong></td>${presets.map(p=>`<td><strong>${estimateLabel(priceOf(p.items))}</strong></td>`).join('')}</tr><tr><td>KIỂM TRA DEMO</td><td>${assessment(selected).score}/100</td>${presets.map(p=>`<td>${assessment(p.items).score}/100</td>`).join('')}</tr></tbody></table></div><div class="section-foot"><div class="footnote">Socket, RAM, tải nguồn, kích thước minh họa; chưa xác minh BIOS, đầu cấp nguồn và kích thước phiên bản thực tế.</div><button class="btn primary" id="exportBtn">XUẤT JSON ↓</button></div></section>`;}
  function setPage(next){comparisonKey=null;comparisonLocked=false;clearTimeout(comparisonExitTimer);page=next;document.querySelectorAll('#nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('breadcrumb').textContent={build:'TỰ BUILD',advisor:'TƯ VẤN',catalog:'KHO LINH KIỆN',compare:'SO SÁNH',stores:'CỬA HÀNG'}[page];render();}
  function render(){renderMetrics();renderRegionToolbar();showPriceSync();document.getElementById('pageView').innerHTML=({build:renderBuild,advisor:renderAdvisor,catalog:renderCatalog,compare:renderCompare,stores:renderStores})[page]();bindPageEvents();}
  function bindPageEvents(){
    document.querySelectorAll('[data-color-mode]').forEach(btn=>btn.addEventListener('click',()=>{
      colorMode=btn.dataset.colorMode;advisorGenerated=false;render();showToast('Đã chọn '+colorNames[colorMode]+'. Kho linh kiện không bị giới hạn.');
    }));
    document.querySelectorAll('[data-color-strict]').forEach(cb=>cb.addEventListener('change',()=>{
      colorPolicy=cb.checked?'strict':'prefer';advisorGenerated=false;render();
    }));

    document.querySelectorAll('[data-store]').forEach(el=>el.addEventListener('click',()=>{storeId=el.dataset.store;render();showToast('Đã đổi cửa hàng; kho linh kiện giữ nguyên');}));
    document.querySelectorAll('[data-part-search]').forEach(input=>input.addEventListener('input',()=>{
      const category=input.dataset.partSearch, select=document.querySelector(`[data-part="${category}"]`);
      if(!select)return;
      const value=selected[category];
      const needle=input.value.toLocaleLowerCase('vi-VN').trim();
      const choices=sortedColorChoices(category,compatibleOptions(category,selected));
      const matches=choices.filter(p=>(p.name+' '+(p.brand||'')+' '+(p.color||'')).toLocaleLowerCase('vi-VN').includes(needle));
      const current=choices.find(p=>p.id===value);
      const shown=current&&!matches.some(p=>p.id===value)?[current,...matches]:matches;
      select.replaceChildren(...shown.map(p=>new Option(p.name+(desiredColor()&&visibleColorCategories.includes(category)?' • '+colorText(category,p):''),p.id,p.id===value,p.id===value)));
      if(!shown.length){select.add(new Option('Không tìm thấy phù hợp',''));select.disabled=true;}else select.disabled=false;
    }));
    document.querySelectorAll('[data-part]').forEach(el=>el.addEventListener('change',()=>{const key=el.dataset.part;const next={...selected,[key]:el.value};const result=normalize(next);selected=result.items;render();if(result.changes.length)showToast('Đã tự đổi '+result.changes.map(x=>x.toUpperCase()).join(', ')+' sang lựa chọn phù hợp');}));
    document.querySelectorAll('.option > [data-apply]').forEach(el=>el.addEventListener('click',()=>applyPreset(el.dataset.apply)));
    bindComparisonEvents();
    bindAdvisorComparison();
    document.getElementById('saveBtn')?.addEventListener('click',save);
    document.getElementById('resetBtn')?.addEventListener('click',()=>{selected=normalize(initial).items;render();showToast('Đã khôi phục cấu hình mẫu');});
    document.querySelectorAll('[data-budget-input]').forEach(el=>{
      el.addEventListener('input',()=>{
        const next=parseBudgetInput(el.value);
        el.setAttribute('aria-invalid',next===null?'true':'false');
        if(next!==null){budget=next;advisorGenerated=false;updateBudgetLive();}
      });
      el.addEventListener('change',()=>{const next=parseBudgetInput(el.value);if(next!==null){budget=next;advisorGenerated=false;}render();});
      el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();el.blur();}});
    });
    document.querySelectorAll('[data-budget-quick]').forEach(el=>el.addEventListener('click',()=>{budget=Number(el.dataset.budgetQuick);advisorGenerated=false;render();}));
    // Keep multi-select answers persistent while following conditional questions.
    document.querySelectorAll('[data-advisor-group]').forEach(el=>el.addEventListener('toggle',()=>{
      if(el.open)advisorExpanded.add(el.dataset.advisorGroup);else advisorExpanded.delete(el.dataset.advisorGroup);
    }));
    document.querySelectorAll('[data-advisor-need]').forEach(el=>el.addEventListener('change',()=>{
      if(el.checked)advisorNeeds.add(el.dataset.advisorNeed);else advisorNeeds.delete(el.dataset.advisorNeed);
      advisorExpanded.add(el.dataset.advisorNeed.split('-')[0]);advisorGenerated=false;advisorSave();render();
    }));
    document.querySelectorAll('[data-advisor-priority]').forEach(el=>el.addEventListener('change',()=>{
      advisorPriorities[el.dataset.advisorPriority]=el.value;advisorGenerated=false;advisorSave();
    }));
    document.querySelectorAll('[data-advisor-answer]').forEach(el=>el.addEventListener('change',()=>{
      const id=el.dataset.advisorAnswer,answer=el.value;
      let set=new Set(Array.isArray(advisorAnswers[id])?advisorAnswers[id]:[]);
      if(el.checked)set.add(answer);else set.delete(answer);
      advisorAnswers[id]=[...set];advisorGenerated=false;advisorSave();render();
    }));
    document.getElementById('advisorClear')?.addEventListener('click',()=>{
      advisorNeeds.clear();advisorAnswers={};advisorPriorities={};advisorGenerated=false;advisorExpanded=new Set(['gaming']);advisorSave();render();
    });
    document.getElementById('advisorGenerate')?.addEventListener('click',()=>{
      if(!advisorNeeds.size)return;
      advisorProposals=advisorGenerateBuilds();advisorGenerated=true;advisorComparisonIndex=null;advisorComparisonLocked=false;render();
      document.getElementById('advisorGenerated')?.scrollIntoView({behavior:'smooth',block:'start'});
    });
    document.getElementById('advisorEdit')?.addEventListener('click',()=>document.querySelector('.advisor-questions-head')?.scrollIntoView({behavior:'smooth',block:'start'}));
    document.querySelectorAll('[data-advisor-apply]').forEach(el=>el.addEventListener('click',()=>applyAdvisorProposal(Number(el.dataset.advisorApply))));
    document.getElementById('catalogSearch')?.addEventListener('input',e=>{catalogQuery=e.target.value;document.getElementById('catalogItems').innerHTML=catalogHTML();});
    document.getElementById('catalogFilter')?.addEventListener('change',e=>{catalogFilter=e.target.value;render();});
    document.getElementById('exportBtn')?.addEventListener('click',()=>{const payload={demo:priceRecords.size<categories.reduce((n,c)=>n+parts[c.id].length,0),priceVerified:priceRecords.size>0,verifiedProductCount:priceRecords.size,lastPriceSync,regionId,storeId,colorMode,colorPolicy,currency:'VND',budget,estimatedTotal:priceOf(selected),items:Object.fromEntries(categories.map(c=>[c.id,partOf(c.id)])),checks:assessment().messages};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='neonrig-build.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Đã xuất JSON');});
  }
  document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
  document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>{setPage(b.dataset.go);document.getElementById('pageView').scrollIntoView({behavior:'smooth',block:'start'});}));
  document.getElementById('homeLink').addEventListener('click',e=>{e.preventDefault();if(typeof window.NEON_SHOW_HOME==='function'){window.NEON_SHOW_HOME();return;}setPage('build');window.scrollTo({top:0,behavior:'smooth'});});
  window.NEON_SET_PC_PAGE=setPage;
  render();
  syncShopPrices();
})();
